  if(/^(domain|remap)/.test(control))return 'Named color domains and Remappen topology';
  if(/^(layout|index)/.test(control)||control==='continueMigrationCandidate')return 'Index layout and migration';
  if(/^template/.test(control)||control.includes('TemplateRegion'))return 'Template image intake, cleanup, placement, and display';
  if(/^(reduction|brush)/.test(control)||['refreshReduction','saveReduction','writeReduction'].includes(control))return 'Manual color-separation reduction draft';
