  if(/^(bulk|finishPaletteBuild)/.test(control)||['exportPack','replacementRulesExport','replacementRulesImport'].includes(control))return 'Batch export and reviewed build';
  if(/^(flow|paletteStep-|paletteWorkflowPanel|section:)/.test(control)||['actions','facts','identity','sections'].includes(control))return 'Guided Palette Workspace navigation';
  if(/^(contact|collective)/.test(control)||['ackContact','acceptMissed','addLater','construct','nextPage','previousPage','organizeCollective'].includes(control))return 'Collective image contact sheet and color review';
  return 'Palette Workspace retained workflow';
